contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool sendReverted;
        c.sendMoney(address(this), sendAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sendReverted = true;
        } else {
            sendReverted = false;
        }

        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(sendReverted || countAfter == countBefore);
    }

    receive() external payable {}
}

