pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 sendAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        bool sendReverted;
        try c.sendMoney(address(this), sendAmount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        assertTrue(sendReverted || countAfter == countBefore);
    }

    function testFuzz_run(uint256 amount, uint256 sendAmount) public {
        _run(amount, sendAmount);
    }

    receive() external payable {}
}
